def is_non_decreasing_with_at_m most_duplicates(nums, max_dup=2):
    """
    Check if the sequence is non-decreasing and each value appears at most max_dup times.
    """
    if not nums:
        return True
    count = 1
    prev = nums[0]
    for i in range(1, len(nums)):
        if nums[i] < prev:
            return False
        if nums[i] == prev:
            count += 1
            if count > max_dup:
                return False
        else:
            prev = nums[i]
            count = 1
    return True

