def has_three_sum_zero(nums):
    nums = sorted(nums)
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l, r = i + 1, n - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s == 0:
                return True
            if s < 0:
                l += 1
            else:
                r -= 1
    return False

