def count_sevens(n):
    """
    Counts occurrences of the digit '7' in all integers from 0 to n-1
    that are divisible by 11 or 13.
    """
    return sum(
        str(x).count('7')
        for x in range(n)
        if x % 11 == 0 or x % 13 == 0
    )
