def has_three_prime_factors(n):
    if n is None:
        return False
    n = abs(n)
    if n < 2:
        return False
    count = 0
    d = 2
    while d * d <= n:
        while n % d == 0:
            count += 1
            n //= d
            if count > 3:
                return False
        d += 1 if d == 2 else 2  # skip even numbers after 2
