def filter_prime_length_words(sentence: str) -> str:
    """
    Filters words in a sentence, retaining only those whose length is a prime number.
    """

    def is_prime(n: int) -> bool:
        """Checks if a number is prime by testing divisibility up to the square root."""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False

        # Check odd divisors from 3 up to sqrt(n)
        limit = int(n**0.5)
        for i in range(3, limit + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split the input string by spaces, filter by length being prime, and join back
    return " ".join(
        word for word in sentence.split() 
        if is_prime(len(word))
    )

# Example usage
if __name__ == "__main__":
    input_sentence = "This is a test sentence with words of varying lengths"
    result = filter_prime_length_words(input_sentence)
    print(result)
